-- Owner instruction: preserve every existing balance. Only append zero-delta protection metadata.
BEGIN;
LOCK TABLE "Student", "Grade", "OpportunityLog", "StudentLeave", "StudentNote", "Exam", "CourseChapter" IN SHARE ROW EXCLUSIVE MODE;
DO $$
DECLARE protected_balances JSONB; item JSONB; actual TEXT; student_row "Student"%ROWTYPE; v_chapter TEXT; v_ids TEXT;
BEGIN
SELECT COALESCE(jsonb_object_agg(id,jsonb_build_array(opportunities,"baseOpportunities",status,"courseId")),'{}'::jsonb) INTO protected_balances FROM "Student";
FOR item IN SELECT value FROM jsonb_array_elements('[{"studentId": "cmqh32z1q00wlju04lml2609b", "before": 1, "after": 1, "fingerprint": "01ba8cfde59a0804220ce62aa5598f04", "grantId": "cmtlia1qr0009l904j9vvs21j", "grantDate": "2026-09-03T12:33:09.460Z"}, {"studentId": "cmqh314np00hfju04q4mv56oq", "before": 1, "after": 1, "fingerprint": "ba68debe3afe3297b4986e60a3a853c3", "grantId": "cmtk6bu6y000pjr04czc5we2u", "grantDate": "2026-09-02T14:10:51.419Z"}, {"studentId": "cmqgzpapc0057jr04rdqwjrfm", "before": 1, "after": 1, "fingerprint": "cdf75d85ee59e787438203c5fc96694f", "grantId": "cmtlwohf60075ozvk0zgvcrn9", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqgzrhtd008rl704r58wpv2d", "before": 1, "after": 1, "fingerprint": "89ab30bff8e94f117b5397c66b9f0a34", "grantId": "cmtlwov6y0093ozvk0pxaf2ym", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqh3294w00qnju0445trnmy6", "before": 1, "after": 1, "fingerprint": "930b14b6beb2b80249ee83f19ec4dfb3", "grantId": "cmtlwnj9e0023ozvk82ukisxh", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqgzq6uz0017l7049b31089w", "before": 1, "after": 1, "fingerprint": "9ee93ed5b0a6f7ba81448c10326bd019", "grantId": "c925124de9abc4ebe87478391", "grantDate": "2026-08-30 16:30:53.102"}, {"studentId": "cmqh1ezda005bju040cc4hrat", "before": 1, "after": 1, "fingerprint": "25b4661901063f4b181398472d0d99a9", "grantId": "cmtlwp6xw00auozvk2h0w4wmj", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqgzr990006nl704twsf2nvl", "before": 1, "after": 1, "fingerprint": "147e99922d134a212771c3f8ef5fbfb1", "grantId": "cmtlwooyx0087ozvks1lj5al1", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqgzr12l00efjr04bzlyymrr", "before": 1, "after": 1, "fingerprint": "f74022773db4315110304ddc1a4c5b1f", "grantId": "cmtlwokxj007oozvkv1rqzkpr", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqh1fd3t008pju04cjkn9o29", "before": 1, "after": 1, "fingerprint": "83733c6c8947512e283177c1ef678c9a", "grantId": "cmtlhfgkk000bi80420hkt6du", "grantDate": "2026-09-03T12:09:22.340Z"}, {"studentId": "cmqh4q7e4004ll704o64vn8hj", "before": 1, "after": 1, "fingerprint": "4bac52f681313b028aaa10dc0755002b", "grantId": "cmtlwo3at004xozvk8f45nd1w", "grantDate": "2026-09-03T19:15:08.308Z"}, {"studentId": "cmqh1hupn008zju04bys58wl7", "before": 2, "after": 2, "fingerprint": "dfdf30d9feb1694816438ebe53204993", "grantId": "cmtn0j8470005lf04an1ytv90", "grantDate": "2026-09-04T13:51:56.887Z"}, {"studentId": "cmqgvralu00h5l804nf312sd8", "before": 1, "after": 1, "fingerprint": "186a1d72c2e17b42677db0d7a066496a", "grantId": "cmtlwofnj006tozvkgllltn7m", "grantDate": "2026-09-03T19:15:08.308Z"}]'::jsonb) LOOP
 SELECT * INTO student_row FROM "Student" WHERE id=item->>'studentId';
 IF NOT FOUND THEN CONTINUE; END IF;
 SELECT md5(jsonb_build_object('student',to_jsonb(s),'grades',(SELECT jsonb_agg(to_jsonb(g) ORDER BY g.id) FROM "Grade" g WHERE g."studentId"=s.id),'logs',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM "OpportunityLog" l WHERE l."studentId"=s.id),'leaves',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM "StudentLeave" l WHERE l."studentId"=s.id),'notes',(SELECT jsonb_agg(to_jsonb(n) ORDER BY n.id) FROM "StudentNote" n WHERE n."studentId"=s.id),'exams',(SELECT jsonb_agg((to_jsonb(e)-'createdAt'-'createdAtSource') ORDER BY e.id) FROM "Exam" e),'chapters',(SELECT jsonb_agg(to_jsonb(c) ORDER BY c.id) FROM "CourseChapter" c))::text) INTO actual FROM "Student" s WHERE s.id=student_row.id;
 IF student_row.opportunities <> (item->>'before')::int OR (item->>'after')::int <> student_row.opportunities THEN RAISE EXCEPTION 'P2 balance preservation review changed: %', student_row.id; END IF;
 IF actual <> item->>'fingerprint' THEN RAISE EXCEPTION 'P2 reviewed student history changed: %; review again before settlement', student_row.id; END IF;
 SELECT "chapterId" INTO STRICT v_chapter FROM "CourseChapter" WHERE "courseId"=student_row."courseId" AND active AND NOT archived;
 SELECT COALESCE(jsonb_agg(id ORDER BY id),'[]'::jsonb)::text INTO v_ids FROM "Grade" WHERE "studentId"=student_row.id;
 INSERT INTO "AuditLog" (id,module,action,details,"time") VALUES ('p2_balance_review_'||student_row.id,'صيانة النظام','تثبيت الرصيد الحالي دون تغيير بناءً على توجيه المالك',jsonb_build_object('review',item,'before',to_jsonb(student_row),'settledGradeIds',v_ids::jsonb,'previousLogs',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM "OpportunityLog" l WHERE l."studentId"=student_row.id))::text,CURRENT_TIMESTAMP);
 INSERT INTO "OpportunityLog" (id,"studentId",action,amount,"requestedAmount","appliedAmount","balanceBefore","balanceAfter","ledgerVersion","settledGradeIds",reason,date,"chapterId") VALUES ('p2_settlement_'||student_row.id,student_row.id,'إعادة تعيين',student_row.opportunities,student_row.opportunities,0,student_row.opportunities,student_row.opportunities,2,v_ids,'حماية P2: تثبيت الرصيد الموجود دون تغيير بتوجيه المالك؛ حفظ السجلات والدرجات السابقة ومنع إعادة احتسابها',CURRENT_TIMESTAMP,v_chapter);
END LOOP;
IF (SELECT COALESCE(jsonb_object_agg(id,jsonb_build_array(opportunities,"baseOpportunities",status,"courseId")),'{}'::jsonb) FROM "Student") IS DISTINCT FROM protected_balances THEN
 RAISE EXCEPTION 'P2 must preserve every student balance, status and enrollment; rolling back';
END IF;
END;
$$;
COMMIT;
